//! Play screen: which layout is on screen, and the judge counts.
//!
//! Approach (after inf_daken_counter_obsw, Apache-2.0): the `JUDGE` label
//! of the judge panel identifies both "this is the play screen" and the
//! layout; the six counts are read digit by digit from fixed cells. All
//! masks and coordinates here come from `resources/<w>x<h>/play.json`,
//! generated by `tools/resgen` from our own labelled screenshots.

use image::RgbImage;
use iu_core::{Judge, PlayLayout};
use serde::{Deserialize, Serialize};

use crate::mask::Mask;

pub const RESOURCE_VERSION: u32 = 1;

/// Where one layout's judge panel is.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct LayoutAnchor {
    pub layout: PlayLayout,
    /// Top-left of the `JUDGE` label mask.
    pub label: [u32; 2],
    /// Top-left of the first digit cell (thousands of PG).
    pub digits: [u32; 2],
}

/// Size and spacing of the digit cells (4 columns × 6 rows).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct DigitGrid {
    pub width: u32,
    pub height: u32,
    pub step_x: u32,
    pub step_y: u32,
}

pub const DIGIT_COLUMNS: u32 = 4;
pub const JUDGE_ROWS: u32 = 6;
/// A cell with this many white pixels or fewer is blank (leading zero area).
const BLANK_MAX_ONES: u32 = 2;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PlayResources {
    pub version: u32,
    pub width: u32,
    pub height: u32,
    pub judge_label: Mask,
    /// A frame is a play screen when the label is within this distance.
    pub label_max_distance: u32,
    pub layouts: Vec<LayoutAnchor>,
    pub digit_grid: DigitGrid,
    /// Masks for 0–9, in order.
    pub digits: Vec<Mask>,
    /// A digit cell further than this from every mask is unreadable.
    pub digit_max_distance: u32,
}

#[derive(Debug, thiserror::Error)]
pub enum ResourceError {
    #[error("play resources are not valid JSON: {0}")]
    Json(#[from] serde_json::Error),
    #[error("play resources are version {0}, this build reads {RESOURCE_VERSION}")]
    Version(u32),
    #[error("play resources are inconsistent: {0}")]
    Invalid(&'static str),
}

#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum JudgeReadError {
    /// A cell matches no digit (overlay, transition, wrong layout…).
    #[error("judge row {row}, column {column} is not a digit (distance {distance})")]
    Unreadable {
        row: u32,
        column: u32,
        distance: u32,
    },
    /// A digit is followed by a blank cell, or a row has no digits.
    #[error("judge row {row} is not a right-aligned number")]
    Malformed { row: u32 },
}

impl PlayResources {
    pub fn from_json(json: &str) -> Result<Self, ResourceError> {
        let res: Self = serde_json::from_str(json)?;
        if res.version != RESOURCE_VERSION {
            return Err(ResourceError::Version(res.version));
        }
        if res.digits.len() != 10 {
            return Err(ResourceError::Invalid("need exactly 10 digit masks"));
        }
        let g = res.digit_grid;
        if res
            .digits
            .iter()
            .any(|m| (m.width(), m.height()) != (g.width, g.height))
        {
            return Err(ResourceError::Invalid("digit masks do not match the grid"));
        }
        Ok(res)
    }

    /// The layout on screen, if this frame is a play screen with the judge
    /// panel visible. Checks only the known anchors, so it is cheap enough
    /// to run on every frame.
    pub fn detect(&self, img: &RgbImage) -> Option<LayoutAnchor> {
        if img.dimensions() != (self.width, self.height) {
            return None;
        }
        self.layouts
            .iter()
            .map(|a| {
                let d = self.judge_label.distance_at(img, a.label[0], a.label[1]);
                (d, a)
            })
            .filter(|(d, _)| *d <= self.label_max_distance)
            .min_by_key(|(d, _)| *d)
            .map(|(_, a)| *a)
    }

    /// Reads the six judge counts at `anchor`.
    pub fn read_judge(
        &self,
        img: &RgbImage,
        anchor: &LayoutAnchor,
    ) -> Result<Judge, JudgeReadError> {
        let mut counts = [0u32; 6];
        for (row, count) in (0..JUDGE_ROWS).zip(counts.iter_mut()) {
            *count = self.read_row(img, anchor, row)?;
        }
        Ok(Judge::from_array(counts))
    }

    fn read_row(
        &self,
        img: &RgbImage,
        anchor: &LayoutAnchor,
        row: u32,
    ) -> Result<u32, JudgeReadError> {
        let g = self.digit_grid;
        let mut value: Option<u32> = None;
        for column in 0..DIGIT_COLUMNS {
            let x = anchor.digits[0] + column * g.step_x;
            let y = anchor.digits[1] + row * g.step_y;
            let cell = Mask::from_image(img, x, y, g.width, g.height);
            if cell.count_ones() <= BLANK_MAX_ONES {
                if value.is_some() {
                    return Err(JudgeReadError::Malformed { row });
                }
                continue;
            }
            let (digit, distance) = self.classify(&cell);
            if distance > self.digit_max_distance {
                return Err(JudgeReadError::Unreadable {
                    row,
                    column,
                    distance,
                });
            }
            value = Some(value.unwrap_or(0) * 10 + digit);
        }
        value.ok_or(JudgeReadError::Malformed { row })
    }

    /// Nearest digit mask and its distance.
    pub fn classify(&self, cell: &Mask) -> (u32, u32) {
        self.digits
            .iter()
            .enumerate()
            .map(|(d, m)| (d as u32, m.distance(cell)))
            .min_by_key(|&(_, dist)| dist)
            .expect("10 digit masks")
    }
}
